def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    slots = int(supply // WATER_REQ)
    competitors = len(alive) + 1

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    if slots >= competitors:
        bid = DAILY_SALARY * 0.12
    elif slots >= 2:
        if highest_prev <= DAILY_SALARY * 0.75:
            bid = max(DAILY_SALARY * 0.58, highest_prev + 1.25)
        else:
            bid = DAILY_SALARY * 0.52
    else:
        if hp <= 2 or no_water_days >= 1:
            bid = max(DAILY_SALARY * 0.92, urgent_high + 2.0)
        elif hp <= 4:
            bid = max(DAILY_SALARY * 0.72, min(urgent_high + 1.5, DAILY_SALARY * 0.9))
        else:
            if highest_prev >= 90:
                bid = DAILY_SALARY * 0.44
            else:
                bid = max(DAILY_SALARY * 0.6, highest_prev + 1.0)

    if hp <= 1:
        bid = max(bid, DAILY_SALARY * 0.98)

    reserve = 0.0
    if hp >= 5 and no_water_days == 0:
        reserve = DAILY_SALARY * 0.15
    final_bid = min(budget - reserve, bid)
    if final_bid < 0:
        final_bid = 0.0
    return float(min(budget, max(0.0, final_bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                prev_hp_after.append(int(hp_after))
            except Exception:
                pass

    base = DAILY_SALARY * 0.55

    # Competitive adjustment: if someone previously bid near high end, slightly increase.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # If my hp is critically low or I've already missed water, bid more.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.9
    elif hp <= 3:
        target = DAILY_SALARY * 0.75
    else:
        # Undercut high bidders unless they were extremely aggressive.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = min(DAILY_SALARY * 0.65, highest_prev_bid - 10.0)
        elif avg_prev_bid >= DAILY_SALARY * 0.75:
            target = min(DAILY_SALARY * 0.6, avg_prev_bid - 5.0)
        else:
            target = base

    # Supply-aware: higher supply reduces urgency, lower supply increases it slightly.
    # supply in [15,25]
    if supply <= float(WATER_REQ):
        target *= 1.15
    else:
        # scale down slightly when abundant
        abundance_factor = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)
        target *= (1.05 - 0.1 * abundance_factor)

    # Clamp to budget and keep non-negative
    bid = max(0.0, min(budget, float(target)))

    # If budget is very small, still bid something minimal to avoid zero-water streak.
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

